import { defineComponent } from 'vue';

import HowToPlayPage from './how-to-play-page.vue';
import { eventEmitter } from '../../services/event-emitter';
import { inversifyContainer } from '../../inversify/container';
import { gameConfig } from '../../models/config-model';

import { Injects } from '../../inversify/injects';
import { device } from '../../services/device';
import { environment } from '../../services/environment';
import { IVueHtpLayout } from '../../types';
import { container, HowToPlayOpenSource, loggingModel } from '../..';

export default defineComponent({
    name: 'HowToPlay',
    components: {
        HowToPlayPage,
    },
    data: () => ({
        tab: 1,
        playbutton: 'play.png',
        selectedColor: '#00736a',
        unselectedColor: '#b1e3e0',
        backgroundColor: '#000000c3',
        unselectedTextColor: '#00736a',
        selectedTextColor: '#ffffff',
        isVisible: false,
        closeBtnImagePath: '',
        showControls: true,
        openedAt: null as number | null,
        openedVia: null as HowToPlayOpenSource | null,
    }),
    mounted: function () {
        if (inversifyContainer.isBound(Injects.VueHtpLayout)) {
            eventEmitter.on('POPUP_TOGGLE_HTP_POPUP', (_, source?: HowToPlayOpenSource) => {
                if (this.howToPlaySections.length > 0) {
                    this.tab = 3;
                    this.toggle(source);
                }
            });

            eventEmitter.on('POPUP_TOGGLE_GAME_INFO', (visibility?: boolean | void, source?: HowToPlayOpenSource) => {
                if (visibility === undefined || visibility === true) {
                    if (this.payTableSections.length > 0) {
                        // open the paytable info
                        this.tab = 1;
                        this.show(source);
                    } else if (this.howToPlaySections.length > 0) {
                        // if no paytable info exists, open the how to play info instead
                        this.tab = 3;
                        this.show(source);
                    }
                }
            });

            // Set backgroundColor from IVueHtpLayout
            this.backgroundColor = inversifyContainer.get<IVueHtpLayout>(Injects.VueHtpLayout).backgroundColor || this.backgroundColor;

            const coreAssetVersion = inversifyContainer.adminSettings.assetVersion.core;
            const assetsBaseUrl = (environment === 'debug' && process.env.LOCALASSETPORT !== void (0)) ?
                `http://127.0.0.1:${process.env.LOCALASSETPORT}/static/assets/`:
                './static/assets/';
            const localAssetFilePath = assetsBaseUrl + 'core/how-to-play/';
            const coreAssetFilePath = assetsBaseUrl + 'core/' + coreAssetVersion + '/how-to-play/';
            this.closeBtnImagePath = gameConfig.features.usingLocalAssets ? localAssetFilePath : coreAssetFilePath;
        }
    },
    methods: {
        getCloseButtonImageURL: function () {
            return `${this.closeBtnImagePath}teal-cross.png`;
        },
        toggle(source?: HowToPlayOpenSource): void {
            this.isVisible ? this.hide() : this.show(source);
        },
        show(source?: HowToPlayOpenSource): void {
            this.isVisible = true;
            
            // begin tracking open time
            this.openedAt = Date.now();
            this.openedVia = source || null;

            eventEmitter.emit('POPUP_HTP_VISIBILITY_CHANGED', this.isVisible);
        },
        hide: function () {
            this.logMetric();
            
            this.isVisible = false;
            this.openedVia = null;

            eventEmitter.emit('POPUP_HTP_VISIBILITY_CHANGED', this.isVisible);
        },
        /** Log that the HTP was open, for how long, where it was opened from and if the nudge has been displayed to the player */
        logMetric: function(): void {
            if (this.openedAt !== null) {
                const duration = Date.now() - this.openedAt;
                const formattedDuration = this.formatDuration(duration);
                const nudgeStatus = container.cabinet.wasHTPNudgeDisplayedThisSession ? 'activated' : 'not activated';
                this.openedAt = null;

                loggingModel.logEvent('HTP_USED', {
                    DURATION: formattedDuration,
                    DURATION_RAW: duration.toString(),
                    OPENED_VIA: this.openedVia || 'unknown',
                    NUDGE_STATUS: nudgeStatus
                });
            }
        },
        formatDuration: function(ms: number): string {
            const seconds = Math.floor(ms / 1000) % 60;
            const minutes = Math.floor(ms / 60_000) % 60;
            const hours = Math.floor(ms / 3_600_000);

            const parts: string[] = [];
            if (hours > 0) parts.push(`${hours}h`);
            if (minutes > 0) parts.push(`${minutes}m`);
            parts.push(`${seconds}s`);

            return parts.join(' ');
        },
        rootStyle: function() {
            return {
                'font-family': inversifyContainer.get<IVueHtpLayout>(Injects.VueHtpLayout).rootFont
            };
        },
        showPlay: function() {
            return inversifyContainer.get<IVueHtpLayout>(Injects.VueHtpLayout).play.length > 0;
        },
        closeStyle: function() {
            return {
                width: '10v' + (device.orientation.isPortrait ? 'w' : 'h'),
                height: '10v' + (device.orientation.isPortrait ? 'w' : 'h')
            };
        },
        select: function (newTab: number) {
            this.tab = newTab;
        },
        assetPath: function (file: string) {
            return '../assets/' + file;
        },
        controlColour: function (tab: number) {
            const colour = tab !== this.tab ? this.unselectedColor : this.selectedColor;
            const textColour = tab !== this.tab ? this.unselectedTextColor : this.selectedTextColor;

            return {
                background: colour,
                color: textColour,
            };
        },
        playButtonColour: function () {
            return this.tab !== 2 ? this.unselectedColor : this.selectedColor;
        },
        localisedString: function(stringName: string) {
            if (inversifyContainer.strings.vueHtp && (stringName in inversifyContainer.strings.vueHtp)) {
                return inversifyContainer.strings.vueHtp[stringName];
            }
            return stringName;
        }
    },
    computed: {
        payTableSections() {
            return inversifyContainer.get<IVueHtpLayout>(Injects.VueHtpLayout).payTable;
        },
        playSections() {
            return inversifyContainer.get<IVueHtpLayout>(Injects.VueHtpLayout).play;
        },
        howToPlaySections() {
            return inversifyContainer.get<IVueHtpLayout>(Injects.VueHtpLayout).howToPlay;
        }
    }
});